additionalExercises.referenceSolution:
#include <iostream>
#include <memory>
#include <vector>
#include <utility>
#include <string>

struct Cell { int* p; explicit Cell(int n): p(new int(n)) {} ~Cell() { delete p; } Cell(const Cell&) = delete; Cell& operator=(const Cell&) = delete; Cell(Cell&& x) noexcept : p(std::exchange(x.p, nullptr)) {} int get() const { return p ? *p : 0; } };
int solve(int a, int b) { Cell source{a}; int saved; { Cell target(std::move(source)); saved = target.get() + b; } return source.get() == 0 ? saved : -9999; }
